// Command kvhttp serves an in-memory key-value store over HTTP/1.1.
//
// Usage:
//
//	app <port>
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"
)

func main() {
	log.SetFlags(0)
	log.SetPrefix("kvhttp: ")

	if len(os.Args) != 2 {
		usage()
	}
	port, err := strconv.Atoi(os.Args[1])
	if err != nil || port < 1 || port > 65535 {
		usage()
	}

	if err := run(port); err != nil {
		log.Fatal(err)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: app <port>")
	os.Exit(2)
}

func run(port int) error {
	ln, err := net.Listen("tcp", net.JoinHostPort("127.0.0.1", strconv.Itoa(port)))
	if err != nil {
		return err
	}

	srv := &http.Server{
		Handler:           NewServer(NewStore()),
		ReadHeaderTimeout: 30 * time.Second,
		ReadTimeout:       60 * time.Second,
		IdleTimeout:       5 * time.Second,
		ErrorLog:          log.Default(),
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		return err
	}
	if err := <-errc; !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}

package main

import (
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"strconv"
	"strings"
)

// MaxValueBytes is the largest value accepted by PUT /kv/<key>.
const MaxValueBytes = 1 << 20

const maxKeyLen = 64

// Server routes HTTP requests to a Store.
type Server struct {
	store *Store
}

// NewServer returns an http.Handler serving the key-value API backed by store.
func NewServer(store *Store) *Server {
	return &Server{store: store}
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	// Route on the raw request target so that escapes like %2F or dot
	// segments are treated literally rather than decoded or cleaned.
	path := requestPath(r)

	switch {
	case path == "/health":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		send(w, http.StatusOK, "text/plain; charset=utf-8", []byte("ok"))

	case path == "/kv":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		s.list(w)

	case strings.HasPrefix(path, "/kv/"):
		key := strings.TrimPrefix(path, "/kv/")
		if !validKey(key) {
			sendError(w, http.StatusBadRequest)
			return
		}
		switch r.Method {
		case http.MethodGet:
			s.get(w, key)
		case http.MethodPut:
			s.put(w, r, key)
		case http.MethodDelete:
			s.delete(w, key)
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodPut, http.MethodDelete)
		}

	default:
		sendError(w, http.StatusNotFound)
	}
}

func (s *Server) list(w http.ResponseWriter) {
	body, err := json.Marshal(s.store.Keys())
	if err != nil {
		log.Printf("encode keys: %v", err)
		sendError(w, http.StatusInternalServerError)
		return
	}
	send(w, http.StatusOK, "application/json", body)
}

func (s *Server) get(w http.ResponseWriter, key string) {
	value, ok := s.store.Get(key)
	if !ok {
		sendError(w, http.StatusNotFound)
		return
	}
	send(w, http.StatusOK, "application/octet-stream", value)
}

func (s *Server) put(w http.ResponseWriter, r *http.Request, key string) {
	if r.ContentLength > MaxValueBytes {
		tooLarge(w)
		return
	}
	value, err := io.ReadAll(http.MaxBytesReader(w, r.Body, MaxValueBytes))
	if err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			tooLarge(w)
			return
		}
		sendError(w, http.StatusBadRequest)
		return
	}
	status := http.StatusCreated
	if s.store.Put(key, value) {
		status = http.StatusOK
	}
	send(w, status, "", nil)
}

func (s *Server) delete(w http.ResponseWriter, key string) {
	if !s.store.Delete(key) {
		sendError(w, http.StatusNotFound)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// requestPath returns the undecoded path of the request target.
func requestPath(r *http.Request) string {
	path, _, _ := strings.Cut(r.RequestURI, "?")
	if !strings.HasPrefix(path, "/") {
		// Absolute-form or asterisk-form target.
		path = r.URL.EscapedPath()
	}
	return path
}

// validKey reports whether key matches [A-Za-z0-9_-]{1,64}.
func validKey(key string) bool {
	if len(key) == 0 || len(key) > maxKeyLen {
		return false
	}
	for i := 0; i < len(key); i++ {
		c := key[i]
		switch {
		case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

// send writes a complete response with an explicit Content-Length.
// A Content-Type is set only when the body is non-empty.
func send(w http.ResponseWriter, status int, contentType string, body []byte) {
	h := w.Header()
	if len(body) > 0 && contentType != "" {
		h.Set("Content-Type", contentType)
	}
	h.Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	if len(body) > 0 {
		_, _ = w.Write(body)
	}
}

func sendError(w http.ResponseWriter, status int) {
	send(w, status, "text/plain; charset=utf-8", []byte(http.StatusText(status)))
}

func methodNotAllowed(w http.ResponseWriter, methods ...string) {
	w.Header().Set("Allow", strings.Join(methods, ", "))
	sendError(w, http.StatusMethodNotAllowed)
}

func tooLarge(w http.ResponseWriter) {
	w.Header().Set("Connection", "close")
	sendError(w, http.StatusRequestEntityTooLarge)
}

package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func do(t *testing.T, h http.Handler, method, target string, body []byte) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(method, target, bytes.NewReader(body))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

func TestRoutes(t *testing.T) {
	h := NewServer(NewStore())
	steps := []struct {
		method, target, body string
		status               int
		want                 string
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/health", "", 405, ""},
		{"GET", "/nope", "", 404, ""},
		{"GET", "/kv/bad.key", "", 400, ""},
		{"GET", "/kv/", "", 400, ""},
		{"GET", "/kv/a/b", "", 400, ""},
		{"GET", "/kv/%41", "", 400, ""},
		{"GET", "/kv/" + strings.Repeat("k", 65), "", 400, ""},
		{"PUT", "/kv/" + strings.Repeat("k", 64), "x", 201, ""},
		{"PUT", "/kv/a", "hello", 201, ""},
		{"GET", "/kv/a", "", 200, "hello"},
		{"PUT", "/kv/a", "", 200, ""},
		{"GET", "/kv/a", "", 200, ""},
		{"PATCH", "/kv/a", "", 405, ""},
		{"POST", "/kv", "", 405, ""},
		{"DELETE", "/kv/a", "", 204, ""},
		{"DELETE", "/kv/a", "", 404, ""},
		{"GET", "/kv/a", "", 404, ""},
	}
	for _, s := range steps {
		rec := do(t, h, s.method, s.target, []byte(s.body))
		if rec.Code != s.status {
			t.Fatalf("%s %s: status %d, want %d", s.method, s.target, rec.Code, s.status)
		}
		if s.want != "" && rec.Body.String() != s.want {
			t.Fatalf("%s %s: body %q, want %q", s.method, s.target, rec.Body.String(), s.want)
		}
	}
}

func TestList(t *testing.T) {
	h := NewServer(NewStore())
	rec := do(t, h, "GET", "/kv", nil)
	if rec.Body.String() != "[]" {
		t.Fatalf("empty list = %q", rec.Body.String())
	}
	for _, k := range []string{"b", "_", "A", "a", "-"} {
		do(t, h, "PUT", "/kv/"+k, []byte("v"))
	}
	rec = do(t, h, "GET", "/kv", nil)
	if ct := rec.Header().Get("Content-Type"); !strings.Contains(ct, "application/json") {
		t.Fatalf("content-type %q", ct)
	}
	var keys []string
	if err := json.Unmarshal(rec.Body.Bytes(), &keys); err != nil {
		t.Fatal(err)
	}
	want := []string{"-", "A", "_", "a", "b"}
	if strings.Join(keys, ",") != strings.Join(want, ",") {
		t.Fatalf("keys %v, want %v", keys, want)
	}
}

func TestValueLimit(t *testing.T) {
	h := NewServer(NewStore())
	big := bytes.Repeat([]byte{0xff}, MaxValueBytes)
	if rec := do(t, h, "PUT", "/kv/big", big); rec.Code != 201 {
		t.Fatalf("1 MiB value: status %d", rec.Code)
	}
	if rec := do(t, h, "GET", "/kv/big", nil); !bytes.Equal(rec.Body.Bytes(), big) {
		t.Fatal("1 MiB value not returned intact")
	}
	if rec := do(t, h, "PUT", "/kv/big", append(big, 0)); rec.Code != 413 {
		t.Fatalf("oversized value: status %d", rec.Code)
	}
}

package main

import (
	"slices"
	"sync"
)

// Store is a concurrency-safe in-memory map from keys to byte values.
type Store struct {
	mu   sync.RWMutex
	data map[string][]byte
}

// NewStore returns an empty Store.
func NewStore() *Store {
	return &Store{data: make(map[string][]byte)}
}

// Get returns the value stored under key and whether it was present.
// The returned slice must not be modified.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// Put stores value under key and reports whether the key already existed.
// The store takes ownership of value.
func (s *Store) Put(key string, value []byte) (replaced bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, replaced = s.data[key]
	s.data[key] = value
	return replaced
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.data[key]
	if ok {
		delete(s.data, key)
	}
	return ok
}

// Keys returns every key in ascending byte order.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := make([]string, 0, len(s.data))
	for k := range s.data {
		keys = append(keys, k)
	}
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}
